      "description": "This ornate headgear comes in many different shapes and sizes, though most are elaborately decorated with motifs of the deity whose honor in which it was made. The miter brings you spiritually closer to your deity's servitors, granting you a +2 item bonus to Religion checks.\nActivate 1 minute (command)\nFrequency once per week\nEffect You chant for a minute about a task at hand for the coming week to cast a 4th-rank Read Omens spell that grants you cryptic but useful advice.",
