      "level": 12,
      "rarity": "rare",
      "traits": [
        "alchemical",
        "consumable",
        "drug",
        "ingested"
      ],
      "description": "Activate 1 Interact\nA synthetic adrenaline supplement that increases awareness and reaction time. Plasma hype has been infused with a specific mixture of Numerian fluids and other alchemical reagents to improve upon the original hype formula.\nSaving Throw check (fortitude, dc:30)\nMaximum Duration 1 minute\nStage 1 +10-foot status bonus to speed, quickened and can use the additional action to Step, Stride, Climb, or Swim (1 round)\nStage 2 quickened and can use the additional action to Step or Stride (1 round)\nStage 3 Drained 2 and Stupefied 2 (1 round)",
      "bulk": 0.1,
      "price": {
        "gp": 400
      },
