      "name": "False Manacles",
      "itemType": "equipment",
      "level": 0,
      "rarity": "uncommon",
      "traits": [],
      "description": "These manacles are nearly indistinguishable from real manacles upon inspection, but contain a hidden release that enables a wearer who knows the location of the release to free themselves with a single Interact action. An observer who examines the manacles and succeeds at a check (perception, dc:20, traits:action:seek) check notices their false nature. On a critical success, the observer finds the location of the hidden catch as well.",
