      "rarity": "uncommon",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "This thin leather cord bears delicate runic markings and threads through an item that can bear affixed talismans.\nWhen you Affix a Talisman to that item, you can thread the talisman onto the cord, activating the cord's preserving effects. The cord is attuned to two particular schools of magic, chosen when the cord was created. It gains the corresponding trait for that school. When you activate a talisman threaded through a cord with the same magic school trait that's also the cord's level or lower, attempt a check (flat, dc:16). On a success, that talisman is not consumed and can be used again.",
