    "data": {
      "schemaVersion": 1,
      "name": "Puzzle Box (Simple) (Hollow)",
      "itemType": "equipment",
      "level": 0,
      "rarity": "common",
      "traits": [],
      "description": "A puzzle box features moving parts, locking mechanisms, and other components designed to confound the user. Solving a puzzle box typically requires three successful DC 15 Games Lore or check (thievery, dc:15, name:Puzzle Box) checks to Open a Lock, though puzzle boxes come in countless configurations and themes, and the GM can determine which skills are appropriate.\nA hollow puzzle box is designed to have an empty compartment in its center, allowing you to hide an object inside of the box. Only someone that solves the puzzle box can access the item within. A hollow puzzle box can hold an item of negligible Bulk no larger than 1 inch in diameter. Any puzzle box can be made into a hollow puzzle box. Doing so doubles the puzzle box's price.",
      "bulk": 0.1,
      "price": {
        "sp": 4
      },
      "usage": "held-in-one-hand",
      "category": "equipment",
      "group": "equipment"
    }
