      "name": "Support",
      "itemType": "equipment",
      "level": 0,
      "rarity": "common",
      "traits": [],
      "description": "Supports, also commonly known as braces, can be applied to any of the following major joints: wrist, elbow, knee, and ankle. They typically strap around the desired area and provide not only support but warmth that soothes aches and pains. You can still use your limb or joint even if you're not wearing your support, but you might feel aches and pains that are worse than usual and may manifest into physical symptoms.",
