      "itemType": "equipment",
      "level": 0,
      "rarity": "common",
      "traits": [],
      "description": "These tiny round balls are made of polished stone and colorful glass, and come in a bag of 200. You can pour marbles in an empty square adjacent to you with an Interact action. The first creature that moves into that square must succeed at a check (acrobatics, dc:13) check or check (reflex, dc:13) save (its choice) or fall Prone. Once a creature enters a space with marbles, enough marbles are scattered that other creatures moving into that space don't need to attempt a roll to avoid falling.",
