      "itemType": "equipment",
      "level": 0,
      "rarity": "rare",
      "traits": [
        "precious"
      ],
      "description": "A blue-green metal with an eerie green luminescence, abysium radiates power that's inimical to life. Careless exposure to the material can lead to long-term damage to the immune system; as such, mining abysium is hazardous, as large quantities of the metal in an area cause all nearby creatures to become sick.\nA creature carrying an abysium object is Sickened 1 for a standard-grade object of light Bulk, Sickened 2 for a standard-grade object of 1 Bulk or more or a high-grade object of light Bulk, or Sickened 3 for a high-grade object of 1 Bulk or more. This and all other sickening effects of abysium are poison effects.\nCrafters can use 1 abysium chunk to create up to 6 doses of poisonous Abysium Powder. Unscrupulous smiths have harnessed abysium's toxic properties to create noxious weapons and deadly substances.\nAll objects crafted from abysium shed dim light in a 10-foot radius.\nAbysium Items\nAbysium Items |\nHardness |\nHP |\nBT |\nThin Items |\n |\n |\n |\nStandard-grade |\n6 |\n24 |\n12 |\nHigh-grade |\n10 |\n40 |\n20 |\nItems |\n |\n |\n |\nStandard-grade |\n10 |\n40 |\n20 |\nHigh-grade |\n13 |\n52 |\n26 |\nStructures |\n |\n |\n |\nStandard-grade |\n20 |\n80 |\n40 |\nHigh-grade |\n26 |\n104 |\n52 |",
