      "itemType": "equipment",
      "level": 0,
      "rarity": "common",
      "traits": [],
      "description": "Bulk L (1 if inflated)\nThis weighted animal bladder can be inflated with air in preparation for a dive. It holds enough air to breathe for one round. As a free action, you can inhale the contents of the air bladder, which resets the number of rounds you can hold your breath. You can inflate the bladder or remove its attached weight as an Interact action. An unattached inflated bladder without the weight will float toward the surface of the water at a rate of 60 feet per round.",
