      "name": "Probing Cane",
      "itemType": "weapon",
      "level": 0,
      "rarity": "common",
      "traits": [
        "finesse",
        "sweep"
      ],
      "description": "Your cane indicates that you have low vision or are blind. By holding this cane in front of you, you indicate to those around that you're partially sighted, which is particularly useful in urban or busy places to let others know to give you enough space. The cane is typically several feet long, generally reaching the user's chin, but can be lengthened or shortened as needed.\nProbing canes are made from reinforced wood with the same strengthening process and treatment as a longbow, creating a cane that is both high quality and durable enough for an adventuring owner to use as a weapon.",
