      "description": "Activate 1 Strike\nThis flask contains a fine red powder made from toxic berries. A lesser vexing vapor bomb deals 1d6 mental damage and 1 splash)[mental damage]. On a hit, the target must succeed at a check (flat, dc:5) check before taking actions with the concentrate trait. This lasts until the end of its next turn (1 minute on a critical hit).",
