      "description": "Hauling weapons are adept at moving creatures around the battlefield after a successful attack.\nActivate R Command\nFrequency once per hour\nTrigger You succeed at an attack roll to Strike with a weapon with the hauling rune\nEffect The target must succeed at a check (reflex, dc:20, name:Hauling Rune) save or be moved 5 feet in a direction you choose. This is forced movement.",
