      "level": 6,
      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "This prosthetic arm is imbued with transmutation magic that can transform it into a weapon.\nActivate 3 command, Interact\nRequirements You are holding a one-handed weapon\nEffect The prosthesis engulfs the weapon and absorbs it entirely. The weapon is unavailable until you use this Activation to release it from the prosthesis. The prosthesis can hold up to two items at a time.\nActivate F envision\nFrequency once per minute\nEffect The prosthesis reshapes into the form of a weapon it has absorbed. The prosthesis has all of the statistics of the weapon, including the effects of any etched runes. The prosthesis remains in this weapon's form until you use this Activation again to revert it back to a prosthesis.",
