      "rarity": "uncommon",
      "traits": [
        "consumable",
        "mechanical",
        "snare",
        "trap",
        "visual"
      ],
      "description": "A mixture of metal shavings and flash powder inside this small, mirrored sphere ignites when disturbed, causing the ball to flash and spin. When a creature enters the square, the ball pops into the air, and all creatures within 10 feet who can see the mirror ball must succeed at a check (fortitude, dc:22, showDC:all) save or become Dazzled for 1 round. On a critical failure, affected creatures are instead dazzled for 1 minute.",
