    "sourceHash": "sha256:d32b29bd99545343f321e721eff9bb4fcdc194feeadae484cd10ee385d0ea618",
    "translatableHash": "sha256:116ca1ff32cdda207723462af222b6e570a657fa8a2d88773357c0b4367d6110",
    "data": {
      "schemaVersion": 1,
      "name": "Waffle Iron (Mithral)",
      "itemType": "equipment",
      "level": 8,
      "rarity": "uncommon",
      "traits": [],
      "description": "This set of hinged metal plates features studs on the inside of each plate to provide a texture for the pastry cakes you cook with it. You pour batter on the plates, close the device, and place it on a fire or stove to cook.\nThe plates of this waffle iron are made of standard-grade dawnsilver rather than iron and might bear an imprint on the plates. As with other dawnsilver cookware, food rarely sticks to a dawnsilver waffle iron. As it's made of dawnsilver, this is an uncommon item.",
      "bulk": 0.1,
      "price": {
        "gp": 355
      },
      "usage": "held-in-one-hand",
      "category": "equipment",
      "group": "equipment"
    }
