      "itemType": "consumable",
      "level": 8,
      "rarity": "uncommon",
      "traits": [
        "alchemical",
        "consumable",
        "elixir"
      ],
      "description": "Your bones, muscles, and organs become vastly softer and more pliable. You can fit into and through small or narrow spaces as though you were 1 size smaller than your normal size (minimum small), and you gain a +2 item bonus to your Fortitude and Reflex DCs against attempts to Grapple, Shove, or Trip you for 1 minute.\nEffect: Malleable Mixture (Lesser)",
