      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "This prosthetic eye was designed by elven crafters but comes in a range of appearances for different ancestries. While wearing the eye, you gain a +1 item bonus to visual Perception checks.\nActivate 2 command, envision\nFrequency once per day\nEffect You focus on the eye to see the unseen. The eye casts See the Unseen on you.",
