      "description": "This finely cut garnet brooch fills your mind with vigor and occasional bursts of mental clarity. While wearing the brooch, you gain a +1 item bonus to checks to Recall Knowledge with Lore skills.\nActivate 2 envision (fortune)\nFrequency once per day\nEffect You think hard on a topic and receive a sudden inspiration. You attempt to Recall Knowledge using Lore. On this check, you roll twice and take the higher result.",
