      "description": "Weapons with this rune empower your strength, and attacks with these weapons leave your foe staggered. When you critically hit a target with this weapon, your target becomes Clumsy 2 and Enfeebled 2 until the end of your next turn.\nEffect: Crushing (Greater)",
