      "description": "This rune prevents enemies from escaping your grasp by Fleeing to other planes. If you critically hit a target with an anchoring weapon, the weapon casts Planar Tether on the target (check (will, dc:27, name:Dimensional Anchor), counteract modifier 1d20+17).",
