    "sourceHash": "sha256:2e556f2d1003d50dc4ffac0204aebc28f02318f9cfd0827e52d613854d3a0ec6",
    "translatableHash": "sha256:9eda3d0c3d5e42471dcf979ab00721ad03511cf6b0a938890cdb76e1d87b123b",
    "data": {
      "schemaVersion": 1,
      "name": "Burning Badger Guts Snare",
      "itemType": "consumable",
      "level": 10,
      "rarity": "uncommon",
      "traits": [
        "consumable",
        "fire",
        "mechanical",
        "snare",
        "trap"
      ],
      "description": "When a creature enters the trapped square, putrefied badger guts coated in hyper-flammable oil and several other incendiary reactants catch fire and are dumped in the snare's square, as well as up to two adjacent squares that you choose when you set the snare. The burning oil deals 5d8 fire damage to any creatures in the affected squares. Those creatures must attempt a check (fortitude, dc:27, options:damaging-effect, showDC:all) save.\nCritical Success The creature is unaffected.\nSuccess The creature takes half damage and 1d8 persistent fire damage.\nFailure The creature takes full damage and 2d8 persistent fire damage, and is Sickened 1.\nCritical Failure As failure, but the creature is Sickened 2.",
      "bulk": 0,
      "price": {
        "gp": 170
      },
      "usage": "held-in-one-hand",
      "category": "snare",
      "group": "consumable"
    }
