    "translatableHash": "sha256:ea984da2da93ce93eda5ac1b3e4032d096e6a6f9c40d506304883423e7a66830",
    "data": {
      "schemaVersion": 1,
      "name": "Juxtaposition Ammunition",
      "itemType": "ammunition",
      "level": 11,
      "rarity": "uncommon",
      "traits": [
        "consumable",
        "magical"
      ],
      "description": "Ammunition any\nActivate 1 Interact\nJuxtaposition ammunition quivers with anticipation, as if the projectile wishes to constantly be in motion. When an activated juxtaposition ammunition hits a creature, it doesn't deal the Strike's normal damage. Instead, the target must succeed at a check (will, dc:28, name:Prevent Teleportation, traits:teleportation, showDC:all) save or be teleported to a safe, unoccupied square of your choice within 60 feet of its original position and within the weapon's first range increment. On a critical failure, the target is also Sickened 1 from the gut-wrenching sensation of sudden movement. Any relocation from the juxtaposition ammunition is forced movement.",
      "bulk": 0,
      "price": {
        "gp": 225
      },
      "usage": "",
      "category": "ammo",
      "group": "ammo"
    }
