      "traits": [
        "force",
        "magical",
        "wand"
      ],
      "description": "This wand juts from an ornate hilt like a short, wooden dagger blade.\nActivate Cast a Spell\nFrequency once per day, plus overcharge\nEffect You cast Spiritual Weapon at 4th-rank. When you critically hit, you apply the weapon's critical specialization effect. In addition, you can etch one of the following property runes onto the wand: corrosive, flaming, frost, shock, thundering, or their respective greater versions. The spiritual weapon's Strikes gain the effects of this rune.\nCraft Requirements Supply a casting of spiritual weapon of 4th-rank.",
