      "itemType": "ammunition",
      "level": 12,
      "rarity": "uncommon",
      "traits": [
        "consumable",
        "magical"
      ],
      "description": "Ammunition arrow, bolt\nActivate 1 Interact\nEach piece of stonethroat ammunition is tipped with an unusual yellow stone. When an activated piece of stonethroat ammunition hits a target, the target must attempt a check (fortitude, dc:30).\nCritical Success The creature is unaffected.\nSuccess The ammunition lodges itself loosely into the target's throat. For 1 round, the target takes a -2 status penalty to attack rolls with its jaws or fangs, and to Athletics checks.\nEffect: Stonethroat Ammunition (Success)\nFailure The ammunition embeds itself deep in the target's throat. The target can't use its jaws or fangs Strike (if it has one) or the Swallow Whole ability until the end of its next turn.\nCritical Failure As failure, and the target is Enfeebled 2 for 1 round.",
