      "description": "The carved night hag's hand at the end of this sandalwood staff clutches a rough gem. The Staff of the Dreamlands makes it easier to navigate and survive in the Dreamlands and recognize its denizens. When wielding the staff, you gain a +1 circumstance bonus to Survival checks while in the Dreamlands and to checks to Recall Knowledge about creatures with the dream trait.\nActivate Cast a Spell\nEffect You expend a number of charges from the staff to cast a spell from its list.\n• Cantrip Daze\n• 1st Alarm, Déjà Vu, Sleep\n• 2nd Phantasmal Treasure, Silence\n• 3rd Dream Message\n• 4th dream message, Nightmare, sleep\n• 5th Dreaming Potential, Illusory Scene\nCraft Requirements Supply one casting of all listed levels of all listed spells.",
