      "itemType": "equipment",
      "level": 12,
      "rarity": "uncommon",
      "traits": [
        "magical"
      ],
      "description": "This rune depicts a specific type of dragon, resizing after application to fit the surface of the item.\nActivate f envision (spellshape)\nRequirements You're receiving a bonus to AC from your dragon's breath cape or shield\nEffect If your next action is to Cast a Spell with an area of effect that deals the same type of damage as the depicted dragon's breath weapon, the spell gains the effects of the Widen Spell feat. The rune can only affect spells of 5th level or lower.",
