    "sourceHash": "sha256:3b1912f73164d049178772f57b8c7adbf4363f3b7fd8e073ed5207f2bda76169",
    "translatableHash": "sha256:87c42022606c3a18535c7a03e54428f3b86604e7b1989d6b1c30b51605d85217",
    "data": {
      "schemaVersion": 1,
      "name": "Psychic Brigandine",
      "itemType": "armor",
      "level": 13,
      "rarity": "uncommon",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "Transparent crystals as hard as steel take the place of metal plates on this suit of +2 greater invisibility splint mail. Also known as a coat of a thousand thoughts in Vudra and Jalmeray, where it was first developed by psychic warriors, it makes your mind an indomitable fortress. You gain resistance 5 to mental damage.\nWhenever you use the armor to become invisible, you also become psychically invisible. Each time you would be affected by an effect with the mental trait while you are invisible, attempt a check (flat, dc:17) check. On a success, it doesn't affect you.",
      "bulk": 1,
      "price": {
        "gp": 3000
      },
      "usage": "",
      "category": "heavy",
      "group": "composite",
      "armor": {
        "armorClassBonus": 5,
        "dexterityCap": 1,
        "checkPenalty": -3,
        "speedPenaltyFeet": -14
      }
    }
